def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    B=R=None
    for r in range(h):
        for c in range(w):
            if g[r][c]==1: B=(r,c)
            elif g[r][c]==2: R=(r,c)
    dr=R[0]-B[0]; dc=R[1]-B[1]
    adr,adc=abs(dr),abs(dc)
    sr=1 if dr>0 else -1; sc=1 if dc>0 else -1
    m=min(adr,adc)
    # blue stub: first step 1 along each axis with lateral rounded, then pure 45, length m-2
    if adr>=adc:
        r0,c0=B[0]+sr, B[1]+(sc*round(adc/adr) if adr else sc)
    else:
        r0,c0=B[0]+(sr*round(adr/adc) if adc else sr), B[1]+sc
    r,c=r0,c0
    for _ in range(max(m-2,0)):
        out[r][c]=3; r+=sr; c+=sc
    # red stroke: diff+1 cells along major axis toward blue, lateral offset round(minor/major) toward blue
    diff=adr-adc if adr>adc else adc-adr
    if adr>=adc:
        off=-sc*round(adc/adr) if adr else 0
        r,c=R[0]-sr, R[1]+off
        for _ in range(diff+1):
            out[r][c]=3; r-=sr
    else:
        off=-sr*round(adr/adc) if adc else 0
        r,c=R[0]+off, R[1]-sc
        for _ in range(diff+1):
            out[r][c]=3; c-=sc
    return out

